    f.onsubmit=e=>{e.preventDefault();const p=data(f);p.slides=Object.values(p.slides||{});for(const key of Object.keys(s.pages)){for(const group of ['cards','steps','faq'])p.pages[key][group]=Object.values(p.pages[key][group]||{});}saveForm(f,'content',p);};
